// Target: 0x0038B890 nvlStopMovie__FP8nvlMovie
// Reference: NVL/PS2/nvl_ps2.cpp:879-919
#define NULL 0
#define assert(x) ((void)0)
#define NVL_MAX_MOVIE_NUM 4

struct nvlMovieSource
{
  int refs;
  char* filename;
  void* buf;
  int bufsize;
};

struct nvlStream;

struct nvlMovie
{
  nvlMovieSource* src;
  nvlStream* s;
  int dataSize;
  int width;
  int height;
  volatile int currentFrame;
  int framesTotal;
  void* decodeBuffer;
  void* tagBuffer;
};

extern struct nvlSystemData_t
{
  int fromIPUHandlerID;
  int toIPUHandlerID;
  int disableToIPU;
  int disableFromIPU;
  nvlMovie* pMovies[NVL_MAX_MOVIE_NUM];
  int runFullAdvance;
  volatile int currentMovieIdx;
  volatile int advanceOK;
  volatile int ioPending;
  volatile int initInterrupts;
} nvlSystemData;

extern void (*nvlFreeFunc)(void*);
void nvlWaitForVB();
void nvlStreamDestroy(nvlStream*);
extern "C" void free(void*);

void nvlStopMovie( nvlMovie* m )
{
  assert( nvlSystemInitialized && m );
/*
  m->flags &= ~NVL_FLAG_PLAYING;
  m->flags |= NVL_FLAG_STOPPING;
  m->src->refs--;
*/
  int i;

  while( !nvlSystemData.advanceOK )
  {
      // Processing a frame
      nvlWaitForVB();
  }

  for( i = 0; i < NVL_MAX_MOVIE_NUM; i++ )
  {
    if( nvlSystemData.pMovies[i] == m )
    {
      break;
    }
  }
  assert( i < NVL_MAX_MOVIE_NUM );
  nvlSystemData.pMovies[i] = NULL;
  m->src->refs--;
  nvlStreamDestroy( m->s );
  if( nvlFreeFunc )
  {
    (*nvlFreeFunc)( m->decodeBuffer );
    (*nvlFreeFunc)( m->tagBuffer );
    (*nvlFreeFunc)( m );
  }
  else
  {
    free( m->decodeBuffer );
    free( m->tagBuffer );
    free( m );
  }
}
